    t[110150] = { name = "Серце Фернуса", fen = "The heart of Fernus is the key to destroy the Fel Crystals and gain access to Gul'dan inside the Gloomspire.", fua = "Серце Фернуса — ключ до знищення Скверних Кристалів і доступу до Ґул'дана у Похмурому Шпилі." }
