    t[110227] = { name = "Листя Морозоцвіту", fen = "Touching these leaves has a nauseous effect.", fua = "Дотик до цього листя викликає нудоту." }
    t[110228] = { name = "Морозна Скалка", fen = "This shard burns to the touch.", fua = "Ця скалка обпікає на дотик." }
    t[110229] = { name = "Обладунок Овінна", fen = "Well-oiled gear for sneaking in the shadows.", fua = "Добре змащене спорядження для скрадання в тінях." }
    t[110232] = { name = "Кинджал Овінна", fen = "Owynn's cherished blade from his adventures in Azeroth.", fua = "Улюблений клинок Овінна з його пригод на Азероті." }
    t[110253] = { name = "Арконітовий Кристал", fen = "Used to power everyday items in draenei society.", fua = "Використовується для живлення повсякденних речей у суспільстві дренеїв." }
    t[110271] = { name = "Арконітовий Пілон", fen = "Used to generate power for the tombs outside Auchindoun, they are sometimes repurposed to power small towns in emergencies.", fua = "Використовувані для живлення гробниць поза Аучиндоном, вони подеколи перепризначаються для живлення малих містечок у надзвичайних ситуаціях." }
    t[110274] = { name = "Наживка для Безщелепного Скрадача", fen = "Useful when fishing in Gorgrond. Kelp is the favorite food of the Jawless Skulker.", fua = "Корисна для риболовлі в Горгронді. Водорості — улюблена їжа безщелепого скрадайла." }
    t[110289] = { name = "Наживка для Гладкого Соні", fen = "Useful when fishing in Nagrand. Fat Sleepers find sweet flavors irresistable.", fua = "Корисна для риболовлі в Награнді. Гладкі соні не можуть встояти перед солодкими ласощами." }
    t[110290] = { name = "Наживка для Сліпого Озерного Осетра", fen = "Useful when fishing in Shadowmoon. The movement of bottom dwelling Sand Crab attracts the attention of Blind Lake Sturgeons.", fua = "Корисна для риболовлі в Тіньовому Місяці. Рух донних піщаних крабів привертає увагу сліпих озерних осетрів." }
    t[110291] = { name = "Наживка для Вогняного Амоніта", fen = "Useful when fishing in Frostfire. Frostfire fruit is lethal to most humanoids, but is the favorite food of the Fire Ammonite.", fua = "Корисна для риболовлі в Морозному Вогні. Плід морозного вогню смертельний для більшості гуманоїдів, але це улюблена їжа вогняного амоніта." }
    t[110292] = { name = "Наживка для Морського Скорпіона", fen = "Useful when fishing in ocean waters. Sea Scorpions like to pull starfish apart and eat their legs one by one.", fua = "Корисна для риболовлі в морських водах. Морські скорпіони люблять розривати морських зірок і по черзі з'їдати їхні промені." }
    t[110293] = { name = "Наживка для Безодневого Вугра-Ковтача", fen = "Useful when fishing at the Spires of Arak. Toadfish have an odd shape that only gulpers manage to eat.", fua = "Корисна для риболовлі у Шпилях Арака. Риба-жаба має дивну форму, яку здатні проковтнути лише вугрі-ковтачі." }
    t[110294] = { name = "Наживка для Чорноводого Батогохвоста", fen = "Useful when fishing in Talador. Soft shell clams are the favorite food of the Blackwater Whiptail.", fua = "Корисна для риболовлі в Таладорі. Молюски з м'якою мушлею — улюблена їжа чорноводого батогохвоста." }
    t[110295] = "Серце Горгорека"
    t[110378] = { name = "Тотем Боргала", fen = "You hear a faint whispering but can't quite make out what is being said.", fua = "Ви чуєте слабкий шепіт, але не можете до пуття розібрати слів." }
    t[110390] = { name = "Таємна Сутність", fen = "This magical residue radiates with arcane energy.", fua = "Ці магічні рештки випромінюють таємну енергію." }
    t[110391] = { name = "Необроблені Кристали Сили", fen = "Although these crystals are rough and unrefined, they radiate with arcane energy.", fua = "Хоча ці кристали грубі й необроблені, вони випромінюють таємну енергію." }
    t[110418] = { name = "Серце Кристалічного Велетня", fen = "The heart is cold to the touch and pulsating with arcane energy.", fua = "Серце холодне на дотик і пульсує таємною енергією." }
    t[110438] = { name = "Купа Стихійного Попелу", fen = "The remains of a lava elemental whose magic has been completely used up.", fua = "Останки лавового елементаля, чия магія повністю вичерпалася." }
    t[110453] = { name = "Записник Теліна", fen = "Yep - there's embarrassing doodles in here, alright.", fua = "Так-так, тут є кілька соромливих карлючок." }
    t[110459] = { name = "Загадковий Перстень", fen = "This ornate ring is lavishly decorated with a \"V\" emblazoned on it.", fua = "Цей вишуканий перстень розкішно оздоблений викарбуваною на ньому літерою \"V\"." }
    t[110469] = { name = "Загадкові Чоботи", fen = "These elaborate boots are lavishly decorated with a \"V\" emblazoned on them.", fua = "Ці витончені чоботи розкішно оздоблені викарбуваною на них літерою \"V\"." }
    t[110470] = { name = "Загадковий Капелюх", fen = "This mystic hat is lavishly decorated with a \"V\" emblazoned on it.", fua = "Цей містичний капелюх пишно оздоблений літерою «V»." }
    t[110471] = { name = "Загадковий Посох", fen = "This magical staff fluxuates in and out of time itself and has the clear symbol of the letter \"V\" on it.", fua = "Цей магічний посох мерехтить у часі й поза ним і має чіткий символ літери «V»." }
