    t[111575] = { name = "Відозва Послідовника", fen = "Reshad of Skettis. Ishaal of Shadowglade. Zellek of Veil Akraz. In the name of Rukhmar, we will burn away the shadows.", fua = "Решад зі Скеттіса. Ішаал із Тіньової Галявини. Зеллек із Завіси Акраз. В ім'я Рукмара ми випалимо тіні." }
