    t[111884] = { name = "Ребра Тіньоскрадача", fen = "Arsenio Zerep will probably be interested in these.", fua = "Арсеніо Зереп напевно цим зацікавиться." }
    t[111885] = { name = "Спора Похмуротіні", fen = "Rumor has it podlings are extremely allergic to these spores.", fua = "Подейкують, що паростки мають надзвичайну алергію на ці спори." }
