    t[112334] = { name = "Спаплюжена Деревина", fen = "Gnarled like the fel-cursed essence of the ancient it came from. Hopefully it won't infect the garrison building Baros plans to build with it.", fua = "Покручена, як проклята скверною сутність прадавня, з якого вона походить. Будемо сподіватися, вона не заразить будівлю гарнізону, яку Барос збирається з неї звести." }
