    t[115272] = { name = "Дослідницький Журнал", fen = "The scientific ramblings of a highly gifted, or incredibly insane mind. It's difficult to tell which....", fua = "Наукові міркування надзвичайно обдарованого або неймовірно божевільного розуму. Важко сказати, що саме..." }
    t[115273] = { name = "Око Анзу", fen = "A spell focus from Terokk's darker days.", fua = "Зосередник чарів із темніших днів Терокка." }
    t[115274] = { name = "Протигрибкові Чоботи", fen = "Some prefer fashionable boots and some desire boots of magical power. Others are simply content with boots that aren't smelly.", fua = "Хтось воліє модні чоботи, а хтось прагне чобіт із магічною силою. Інші ж просто задоволені чоботами, що не смердять." }
    t[115275] = { name = "Припаси Експедиції", fen = "A standard issue Nesingwary supply kit consisting of bullets and beer... but mostly bullets.", fua = "Стандартний набір припасів Несінгварі, що складається з куль і пива... але переважно з куль." }
    t[115276] = { name = "Грибні Спори", fen = "The Zangar fungal strain is highly adaptive and believed to be unique to Draenor.", fua = "Зангарський штам грибів дуже пристосовний і, як вважають, властивий лише Дренору." }
    t[115277] = { name = "Грибний Мозок", fen = "A soft, convoluted mass of fungi exerting centralized control over the body of a spore giant.", fua = "М'яка, звивиста маса грибів, що централізовано керує тілом спорового велета." }
    t[115279] = { name = "Поцуплені Деталі", fen = "Former property of the Iron Horde.", fua = "Колишня власність Залізної Орди." }
    t[115280] = { name = "Камінь Скасування", fen = "An ugly, oddly-shaped gem that nonetheless thrums with residual magical energy.", fua = "Бридкий, дивної форми самоцвіт, що, попри все, гуде залишковою магічною енергією." }
    t[115287] = { name = "Вишуканий Багряний Підвісок", fen = "Warm to the touch.", fua = "Теплий на дотик." }
    t[115288] = { name = "Фоліант Скверноборця", fen = "The pages are blank. Completely blank! Maybe Khadgar can figure it out.", fua = "Сторінки порожні. Геть порожні! Може, Хадґар у цьому розбереться." }
    t[115289] = { name = "Сигіл Короля-Чародія", fen = "A ring the size of your fist, engraved with Mar'gok's personal seal and buzzing with magical power.", fua = "Перстень завбільшки з ваш кулак, гравірований особистою печаткою Мар'гока й сповнений магічної сили." }
    t[115290] = { name = "Посох Ору'кая", fen = "Time appears to slow down in the vicinity of the staff.", fua = "Поблизу цього посоха час, здається, сповільнюється." }
