    t[115493] = { name = "Фоліант Полум'яника", fen = "An iron-bound sheaf of writing - some orcish and some in a language you don't recognize - that appears to have been passed down for generations.", fua = "Скута залізом в'язка писань — частина орчиною, частина невідомою вам мовою, — що, схоже, передавалася з покоління в покоління." }
    t[115494] = { name = "Дренейська Тавматургічна Сфера", fen = "The orb is completely featureless and unadorned, indistinguishable from a polished rock.", fua = "Сфера геть позбавлена будь-яких рис та оздоблення, її не відрізнити від відполірованого каменя." }
