    t[116747] = { name = "Сторінка з Рибальського Щоденника Ната", fen = "Ripped directly from Nat's private fishing journal.", fua = "Вирвана просто з особистого рибальського щоденника Ната." }
    t[116748] = { name = "Вогняний Амоніт-Велетень", fen = "A magical \"fish\" that lives in lava and looks like a squid in a cone shaped shell. Only caught by masterful anglers with the help of Nat Pagle.", fua = "Магічна «риба», що живе в лаві й схожа на кальмара в конусоподібній мушлі. Її виловлюють лише вправні рибалки за допомогою Ната Пейґла." }
    t[116749] = { name = "Чорноводий Батогохвіст-Велетень", fen = "Has a powerful tail, which it uses to stun its prey. Only caught by masterful anglers with the help of Nat Pagle.", fua = "Має потужний хвіст, яким приголомшує здобич. Його виловлюють лише вправні рибалки за допомогою Ната Пейґла." }
    t[116750] = { name = "Сліпий Озерний Осетер-Велетень", fen = "Lacking eyes, it \"sees\" with its long whiskers. Only caught by masterful anglers with the help of Nat Pagle.", fua = "Без очей він \"бачить\" своїми довгими вусами. Виловити його під силу лише вправним рибалкам за допомогою Ната Пейгла." }
    t[116751] = { name = "Безодній Ковтач-Велетень", fen = "With a ridiculously oversized head and mouth, it can swallow prey bigger than itself. Only caught by masterful anglers with the help of Nat Pagle.", fua = "Зі сміховинно завеликою головою й ротом він може ковтати здобич, більшу за себе. Його виловлюють лише вправні рибалки за допомогою Ната Пейґла." }
    t[116752] = { name = "Безщелепний Скрадач-Велетень", fen = "A strange fish with no mouth and an unforked tail.  Subsists on the life energy of plants. Only caught by masterful anglers with the help of Nat Pagle.", fua = "Дивна риба без рота й з нерозвоєним хвостом. Живиться життєвою енергією рослин. Її виловлюють лише вправні рибалки за допомогою Ната Пейґла." }
    t[116753] = { name = "Жирний Соня-Велетень", fen = "Ugly and slimy. Surprisingly delicious when cooked. Only caught by masterful anglers with the help of Nat Pagle.", fua = "Бридка й слизька. Напрочуд смачна в готовому вигляді. Її виловлюють лише вправні рибалки за допомогою Ната Пейґла." }
    t[116754] = { name = "Розжарений Сом", fen = "A prime example of Draenor fish species.", fua = "Чудовий зразок риб'ячих видів Дренору." }
