    t[128228] = { name = "Креслення Спорядження: Резервуар з Дресированими Акулами", fen = "Mines are no match for a tank of trained sharks.", fua = "Міни безсилі проти резервуара з дресированими акулами." }
    t[128229] = { name = "Принада для Скверноротого Шаленця", fen = "Useful when fishing in Tanaan Jungle. The Felmouth Frenzy will feed on any meat - the more putrid, the better.", fua = "Корисна під час риболовлі в Джунглях Танаану. Скверноротий шаленець жертиме будь-яке м'ясо - чим гнилкіше, тим краще." }
    t[128230] = { name = "Креслення Спорядження: Протитуманні Ліхтарі Високої Потужності", fen = "Burn through the fog (and maybe some retinas) with these super illuminating lights.", fua = "Пробивайте туман (а може, і чиїсь сітківки) цими надяскравими ліхтарями." }
    t[128264] = { name = "Креслення Спорядження: Непотоплюваність", fen = "On a devastating hit, saves the ship by surrounding the ship with an impenetrable shield. Unsinkable is destroyed when triggered.", fua = "При нищівному влучанні рятує корабель, огортаючи його непробивним щитом. Непотоплюваність руйнується при спрацюванні." }
    t[128265] = { name = "Креслення Спорядження: Рибальська Сітка Тускарів", fen = "A fishing net attached to the back of the boat, courtesy of the tuskarr.  Supplies fish when returning from a successful mission.", fua = "Рибальська сітка, прикріплена до корми човна, люб'язно надана тускарами. Постачає рибу при поверненні з успішної місії." }
    t[128266] = { name = "Креслення Спорядження: Кермо зі Справжнього Заліза", fen = "Reinforces the rudder to allow tighter turns at higher speeds.", fua = "Зміцнює кермо, дозволяючи крутіші повороти на вищих швидкостях." }
    t[128267] = { name = "Креслення Спорядження: Поле Звукового Підсилення", fen = "Increases success chance when on a mission with a Destroyer.", fua = "Підвищує шанс успіху в місії з есмінцем." }
    t[128268] = { name = "Креслення Спорядження: Шумові Міни Q-43", fen = "Increases success chance when on a mission with a Submarine.", fua = "Підвищує шанс успіху в місії з підводним човном." }
    t[128269] = { name = "Креслення Спорядження: Криголам", fen = "Slices a path through Icy Waters.", fua = "Прорубує шлях крізь крижані води." }
    t[128270] = { name = "Креслення Спорядження: Внутрішній Гіроскопічний Стабілізатор", fen = "Keeps the ship upright and stable, allowing it to move effortlessly around Chaotic Whirlpools.", fua = "Тримає корабель рівно й стійко, дозволяючи йому легко оминати хаотичні виру." }
    t[128271] = { name = "Креслення Спорядження: Примарна Підзорна Труба", fen = "A long spyglass that seems to display nothing when you look through it.  Maybe it will come in handy.", fua = "Довга підзорна труба, крізь яку, здається, нічого не видно. Можливо, вона ще стане в пригоді." }
    t[128272] = { name = "Креслення Спорядження: Пускачі Скверного Диму", fen = "Creates a smoke screen around your ship, blocking sight on a First Strike.", fua = "Створює димову завісу навколо вашого корабля, перешкоджаючи першому удару ворога." }
    t[128273] = { name = "Креслення Спорядження: Додаткові Каюти", fen = "Increases success chance when on a mission with a Transport.", fua = "Підвищує шанс успіху в місії з транспортником." }
    t[128274] = { name = "Креслення Спорядження: Доменна Піч", fen = "A massive furnace, capable of producing 11 out of 10 power.", fua = "Велетенська піч, здатна виробляти потужність 11 з 10." }
    t[128275] = { name = "Креслення Спорядження: Автоматичний Небесний Сканер", fen = "Increases success chance when on a mission with a Carrier.", fua = "Підвищує шанс успіху в місії з авіаносцем." }
    t[128276] = { name = "Креслення Спорядження: Запаси Боєприпасів", fen = "Increases success chance when on a mission with a Battleship.", fua = "Підвищує шанс успіху в місії з лінкором." }
