    t[128428] = { name = "Ритуальний Клинок Кривавого Ока", fen = "An enchanted curved blade used to carve blood sigils onto flesh.", fua = "Зачарований вигнутий клинок, яким вирізають криваві сигіли на плоті." }
    t[128429] = { name = "Морський Маніфест Залізної Орди", fen = "Invaluable details about shipping routes and schedules.", fua = "Безцінні подробиці про судноплавні маршрути та розклади." }
    t[128431] = { name = "Флакон Скверної Крові", fen = "Still warm to the touch, long after you've stopped its victim's heart.", fua = "Досі теплий на дотик, хоча серце його власника давно зупинилося." }
    t[128432] = { name = "Депеша Ради Тіней", fen = "Lists of names and places, some in code. Valuable information capable of unraveling Gul'dan's operations in Tanaan.", fua = "Списки імен і місць, частина зашифрована. Цінні відомості, здатні зруйнувати плани Ґул'дана в Танаані." }
    t[128433] = { name = "Неочищений Дренейський Кристал", fen = "Even in its uncut form, the mineral pulses with power whenever magic is cast nearby.", fua = "Навіть у неогранованому вигляді мінерал пульсує силою щоразу, коли поруч твориться магія." }
    t[128434] = { name = "Збруя Бойового Ґронна", fen = "Engineered so the big beast hardly notices the weight and can fire the cannons at will.", fua = "Сконструйована так, що велетенський звір майже не помічає ваги й може стріляти з гармат досхочу." }
